CREATE FUNCTION "studygraph_assert_citation_before_verify"() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE ref_count integer; BEGIN IF NEW."status"::text = ANY (TG_ARGV[2:]) THEN EXECUTE format( 'SELECT count(*) FROM %I WHERE %I = $1', TG_ARGV[0], TG_ARGV[1] ) INTO ref_count USING NEW."id"; IF ref_count = 0 THEN RAISE EXCEPTION '% % cannot be % without at least one source span citation', TG_TABLE_NAME, NEW."id", NEW."status" USING ERRCODE = 'check_violation', HINT = 'Insert the citation row first, then set status.'; END IF; END IF; RETURN NEW; END; $$;

CREATE TRIGGER "concept_verified_needs_citation" BEFORE INSERT OR UPDATE OF "status" ON "Concept" FOR EACH ROW EXECUTE FUNCTION "studygraph_assert_citation_before_verify"( 'ConceptCitation', 'conceptId', 'VERIFIED', 'PENDING_REVIEW');

CREATE TRIGGER "method_verified_needs_citation" BEFORE INSERT OR UPDATE OF "status" ON "Method" FOR EACH ROW EXECUTE FUNCTION "studygraph_assert_citation_before_verify"( 'MethodCitation', 'methodId', 'VERIFIED', 'PENDING_REVIEW');

CREATE TRIGGER "problem_verified_needs_citation" BEFORE INSERT OR UPDATE OF "status" ON "Problem" FOR EACH ROW EXECUTE FUNCTION "studygraph_assert_citation_before_verify"( 'ProblemCitation', 'problemId', 'VERIFIED');

CREATE FUNCTION "studygraph_downgrade_when_last_citation_removed"() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE citation_table text := TG_ARGV[0]; fk_column text := TG_ARGV[1]; parent_table text := TG_ARGV[2]; target_status text := TG_ARGV[3]; parent_id text := to_jsonb(OLD) ->> fk_column; remaining integer; BEGIN IF parent_id IS NULL THEN RETURN OLD; END IF; EXECUTE format('SELECT count(*) FROM %I WHERE %I = $1', citation_table, fk_column) INTO remaining USING parent_id; IF remaining = 0 THEN EXECUTE format( 'UPDATE %I SET "status" = %L WHERE "id" = $1 AND "status"::text = ANY ($2)', parent_table, target_status ) USING parent_id, TG_ARGV[4:]; END IF; RETURN OLD; END; $$;

CREATE TRIGGER "concept_citation_delete_downgrade" AFTER DELETE ON "ConceptCitation" FOR EACH ROW EXECUTE FUNCTION "studygraph_downgrade_when_last_citation_removed"( 'ConceptCitation', 'conceptId', 'Concept', 'UNVERIFIED', 'VERIFIED', 'PENDING_REVIEW');

CREATE TRIGGER "method_citation_delete_downgrade" AFTER DELETE ON "MethodCitation" FOR EACH ROW EXECUTE FUNCTION "studygraph_downgrade_when_last_citation_removed"( 'MethodCitation', 'methodId', 'Method', 'UNVERIFIED', 'VERIFIED', 'PENDING_REVIEW');

CREATE TRIGGER "problem_citation_delete_downgrade" AFTER DELETE ON "ProblemCitation" FOR EACH ROW EXECUTE FUNCTION "studygraph_downgrade_when_last_citation_removed"( 'ProblemCitation', 'problemId', 'Problem', 'PENDING', 'VERIFIED');

CREATE VIEW "v_problem_distractor_without_error_tag" AS SELECT p."id" AS "problemId", p."canvasId" AS "canvasId", p."status" AS "status", opt."value" AS "option" FROM "Problem" p CROSS JOIN LATERAL jsonb_array_elements( CASE WHEN jsonb_typeof(p."options") = 'array' THEN p."options" ELSE '[]'::jsonb END ) AS opt("value") WHERE p."type" IN ('SINGLE_CHOICE', 'MULTI_CHOICE') AND COALESCE(opt."value" ->> 'errorTag', '') = '' AND NOT ( CASE WHEN jsonb_typeof(p."answer") = 'array' THEN (p."answer" ? (opt."value" ->> 'key')) ELSE (p."answer" ->> 'key') = (opt."value" ->> 'key') END );

CREATE VIEW "v_verified_without_citation" AS SELECT 'Concept'::text AS "kind", c."id" AS "entityId" FROM "Concept" c WHERE c."status" IN ('VERIFIED', 'PENDING_REVIEW') AND NOT EXISTS (SELECT 1 FROM "ConceptCitation" cc WHERE cc."conceptId" = c."id") UNION ALL SELECT 'Method'::text, m."id" FROM "Method" m WHERE m."status" IN ('VERIFIED', 'PENDING_REVIEW') AND NOT EXISTS (SELECT 1 FROM "MethodCitation" mc WHERE mc."methodId" = m."id") UNION ALL SELECT 'Problem'::text, pr."id" FROM "Problem" pr WHERE pr."status" = 'VERIFIED' AND NOT EXISTS (SELECT 1 FROM "ProblemCitation" pc WHERE pc."problemId" = pr."id");

CREATE VIEW "v_paper_with_coverage_gap" AS SELECT pp."id" AS "paperId", pp."title" AS "title", pp."report" AS "report" FROM "Paper" pp WHERE pp."status" = 'READY' AND jsonb_array_length( CASE WHEN jsonb_typeof(pp."report" -> 'gaps') = 'array' THEN pp."report" -> 'gaps' ELSE '[]'::jsonb END ) > 0;

CREATE VIEW "v_method_concept_mismatch" AS WITH step_concepts AS ( SELECT m."id" AS "methodId", CASE WHEN (s."value" ->> 'order') ~ '^[0-9]+$' THEN (s."value" ->> 'order')::int ELSE s."ord"::int END AS "stepOrder", c."value" AS "conceptId" FROM "Method" m CROSS JOIN LATERAL jsonb_array_elements( CASE WHEN jsonb_typeof(m."steps") = 'array' THEN m."steps" ELSE '[]'::jsonb END ) WITH ORDINALITY AS s("value", ord) CROSS JOIN LATERAL jsonb_array_elements_text( CASE WHEN jsonb_typeof(s."value" -> 'conceptIds') = 'array' THEN s."value" -> 'conceptIds' ELSE '[]'::jsonb END ) AS c("value") ) SELECT 'STEP_WITHOUT_METHODCONCEPT'::text AS "mismatch", st."methodId" AS "methodId", st."conceptId" AS "conceptId", st."stepOrder" AS "stepOrder" FROM step_concepts st LEFT JOIN "MethodConcept" mc ON mc."methodId" = st."methodId" AND mc."conceptId" = st."conceptId" WHERE mc."methodId" IS NULL UNION ALL SELECT 'METHODCONCEPT_NOT_IN_STEPS'::text, mc."methodId", mc."conceptId", NULL::int FROM "MethodConcept" mc WHERE NOT EXISTS ( SELECT 1 FROM step_concepts st WHERE st."methodId" = mc."methodId" AND st."conceptId" = mc."conceptId" ) UNION ALL SELECT 'STEP_CONCEPT_MISSING'::text, st."methodId", st."conceptId", st."stepOrder" FROM step_concepts st WHERE NOT EXISTS ( SELECT 1 FROM "Concept" c WHERE c."id" = st."conceptId" );
